public interface IChecklistService
{
    // ... mevcut metodlar ...

    // YENİ METODLAR
    Task<QuestionDto> CopyQuestionAsync(Guid checklistId, Guid sectionId, Guid questionId, int? newOrder = null);
    Task<SectionDto> CopySectionAsync(Guid checklistId, Guid sectionId, int? newOrder = null);
}

public async Task<QuestionDto> CopyQuestionAsync(
    Guid checklistId,
    Guid sectionId,
    Guid questionId,
    int? newOrder = null)
{
    // Checklist ve section'ı al
    var checklist = await _checklistRepository.GetByIdAsync(checklistId, includeDetails: true);
    if (checklist == null)
        throw new KeyNotFoundException($"Checklist with ID {checklistId} not found");

    var section = checklist.Sections.FirstOrDefault(s => s.Id == sectionId);
    if (section == null)
        throw new KeyNotFoundException($"Section with ID {sectionId} not found");

    // Kopyalanacak soruyu bul
    var originalQuestion = section.Questions.FirstOrDefault(q => q.Id == questionId);
    if (originalQuestion == null)
        throw new KeyNotFoundException($"Question with ID {questionId} not found");

    // Yeni sıra numarası belirle
    var order = newOrder ?? section.Questions.Max(q => q.Order) + 1;

    // Soruyu kopyala
    var copiedQuestion = new Question
    {
        SectionId = sectionId,
        Text = $"{originalQuestion.Text} (Kopya)",  // "Kopya" etiketi ekle
        Description = originalQuestion.Description,
        Hint = originalQuestion.Hint,
        Type = originalQuestion.Type,
        Order = order,
        Points = originalQuestion.Points,
        AllowNA = originalQuestion.AllowNA,
        IsRequired = originalQuestion.IsRequired,
        OptionsJson = originalQuestion.OptionsJson
    };

    section.Questions.Add(copiedQuestion);
    await _checklistRepository.UpdateAsync(checklist);

    // DTO'ya çevir ve döndür
    return new QuestionDto
    {
        Id = copiedQuestion.Id,
        Text = copiedQuestion.Text,
        Description = copiedQuestion.Description,
        Hint = copiedQuestion.Hint,
        Type = copiedQuestion.Type.ToString(),
        Order = copiedQuestion.Order,
        Points = copiedQuestion.Points,
        AllowNA = copiedQuestion.AllowNA,
        IsRequired = copiedQuestion.IsRequired,
        Options = ParseQuestionOptions(copiedQuestion.OptionsJson)
    };
}

public async Task<SectionDto> CopySectionAsync(
    Guid checklistId,
    Guid sectionId,
    int? newOrder = null)
{
    // Checklist'i al
    var checklist = await _checklistRepository.GetByIdAsync(checklistId, includeDetails: true);
    if (checklist == null)
        throw new KeyNotFoundException($"Checklist with ID {checklistId} not found");

    // Kopyalanacak section'ı bul
    var originalSection = checklist.Sections.FirstOrDefault(s => s.Id == sectionId);
    if (originalSection == null)
        throw new KeyNotFoundException($"Section with ID {sectionId} not found");

    // Yeni sıra numarası belirle
    var order = newOrder ?? checklist.Sections.Max(s => s.Order) + 1;

    // Section'ı ve içindeki tüm soruları kopyala
    var copiedSection = new Section
    {
        ChecklistId = checklistId,
        Name = $"{originalSection.Name} (Kopya)",
        Description = originalSection.Description,
        Order = order,
        Questions = originalSection.Questions.Select((q, index) => new Question
        {
            Text = q.Text,  // Sorularda "Kopya" yazmaya gerek yok
            Description = q.Description,
            Hint = q.Hint,
            Type = q.Type,
            Order = q.Order,
            Points = q.Points,
            AllowNA = q.AllowNA,
            IsRequired = q.IsRequired,
            OptionsJson = q.OptionsJson
        }).ToList()
    };

    checklist.Sections.Add(copiedSection);
    await _checklistRepository.UpdateAsync(checklist);

    // DTO'ya çevir ve döndür
    return new SectionDto
    {
        Id = copiedSection.Id,
        Name = copiedSection.Name,
        Description = copiedSection.Description,
        Order = copiedSection.Order,
        Questions = copiedSection.Questions.OrderBy(q => q.Order).Select(q => new QuestionDto
        {
            Id = q.Id,
            Text = q.Text,
            Description = q.Description,
            Hint = q.Hint,
            Type = q.Type.ToString(),
            Order = q.Order,
            Points = q.Points,
            AllowNA = q.AllowNA,
            IsRequired = q.IsRequired,
            Options = ParseQuestionOptions(q.OptionsJson)
        }).ToList()
    };
}

[HttpPost("{checklistId}/sections/{sectionId}/questions/{questionId}/copy")]
public async Task<ActionResult<QuestionDto>> CopyQuestion(
    Guid checklistId,
    Guid sectionId,
    Guid questionId,
    [FromQuery] int? newOrder = null)
{
    try
    {
        var result = await _checklistService.CopyQuestionAsync(
            checklistId,
            sectionId,
            questionId,
            newOrder);

        return Ok(result);
    }
    catch (KeyNotFoundException ex)
    {
        return NotFound(ex.Message);
    }
}

[HttpPost("{checklistId}/sections/{sectionId}/copy")]
public async Task<ActionResult<SectionDto>> CopySection(
    Guid checklistId,
    Guid sectionId,
    [FromQuery] int? newOrder = null)
{
    try
    {
        var result = await _checklistService.CopySectionAsync(
            checklistId,
            sectionId,
            newOrder);

        return Ok(result);
    }
    catch (KeyNotFoundException ex)
    {
        return NotFound(ex.Message);
    }
}
